import path from "node:path";

export const lifecycleGeneratedComment =
  "// Generated by scripts/generate-deployable-lifecycles.mjs. Do not edit by hand.\n";
export const lifecycleGeneratedFileMarker = `${lifecycleGeneratedComment}\n`;

export const deployableLifecycleConfig = {
  "catalog-api": {
    fileParts: ["deployables", "catalog-api", "src", "context-lifecycle.generated.ts"],
  },
  "identity-api": {
    fileParts: ["deployables", "identity-api", "src", "context-lifecycle.generated.ts"],
  },
  "inventory-api": {
    fileParts: ["deployables", "inventory-api", "src", "context-lifecycle.generated.ts"],
  },
  "marketplace-api": {
    fileParts: ["deployables", "marketplace-api", "src", "context-lifecycle.generated.ts"],
  },
};

export function resolveDeployableLifecyclePath(repoRoot, deployable) {
  const config = deployableLifecycleConfig[deployable];
  if (!config) {
    throw new Error(`Unknown deployable lifecycle config: ${deployable}`);
  }

  return path.join(repoRoot, ...config.fileParts);
}

function sortContextsBySeedRequirements(contexts) {
  const contextsByName = new Map(contexts.map((context) => [context.contextName, context]));
  const incomingCounts = new Map(contexts.map((context) => [context.contextName, 0]));
  const dependentsByProvider = new Map(contexts.map((context) => [context.contextName, new Set()]));

  for (const context of contexts) {
    for (const providerName of context.seedRequirements ?? []) {
      if (!contextsByName.has(providerName)) {
        throw new Error(
          `Deployable '${context.deployable}' cannot resolve seed requirement '${providerName}' required by '${context.contextName}'.`,
        );
      }

      if (providerName === context.contextName) {
        throw new Error(
          `Context '${context.contextName}' cannot require itself in seedRequirements.`,
        );
      }

      const dependents = dependentsByProvider.get(providerName);
      if (!dependents?.has(context.contextName)) {
        dependents?.add(context.contextName);
        incomingCounts.set(
          context.contextName,
          (incomingCounts.get(context.contextName) ?? 0) + 1,
        );
      }
    }
  }

  const ready = [...contexts]
    .filter((context) => (incomingCounts.get(context.contextName) ?? 0) === 0)
    .map((context) => context.contextName)
    .sort();
  const sorted = [];

  while (ready.length > 0) {
    const contextName = ready.shift();
    const context = contextsByName.get(contextName);
    if (!context) {
      continue;
    }

    sorted.push(context);

    for (const dependentName of dependentsByProvider.get(contextName) ?? []) {
      const nextCount = (incomingCounts.get(dependentName) ?? 0) - 1;
      incomingCounts.set(dependentName, nextCount);
      if (nextCount === 0) {
        ready.push(dependentName);
        ready.sort();
      }
    }
  }

  if (sorted.length !== contexts.length) {
    throw new Error(
      `Deployable '${contexts[0]?.deployable ?? "unknown"}' contains a cycle in seedRequirements.`,
    );
  }

  return sorted;
}

export function buildLifecycleFileContent(unsortedContexts) {
  if (unsortedContexts.length === 0) {
    return `${lifecycleGeneratedFileMarker}export async function seedContextRuntimeIfEmpty(): Promise<void> {
  return undefined;
}
`;
  }

  const sorted = sortContextsBySeedRequirements(unsortedContexts);
  const orderedContextNames = sorted.map((context) => context.contextName);

  return `${lifecycleGeneratedFileMarker}import { drainProjectors, seedApiModulesIfEmpty } from "@chase-sets/bounded-context-runtime";
import type { PgTransactionalPool } from "@chase-sets/event-core-postgres";
import type { createContextRuntime } from "./context-runtime.generated";

const lifecycleContextOrder = ${JSON.stringify(orderedContextNames, null, 2)} as const;

export async function seedContextRuntimeIfEmpty(
  pool: PgTransactionalPool,
  runtime: ReturnType<typeof createContextRuntime>,
): Promise<void> {
  const mountedModulesByName = new Map(
    runtime.mountedModules.map(({ module }) => [module.contextName, module]),
  );
  const orderedModules = lifecycleContextOrder.map((contextName) => {
    const module = mountedModulesByName.get(contextName);
    if (!module) {
      throw new Error(
        \`Runtime is missing mounted module '\${contextName}' required by generated lifecycle order.\`,
      );
    }

    return module;
  });

  await seedApiModulesIfEmpty(orderedModules, pool);
  await drainProjectors(runtime.projectors);
}
`;
}
